CREATE TABLE `Niche` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `Niche_name_key` (`name`));
CREATE TABLE `PipelineStage` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `sortOrder` INTEGER NOT NULL DEFAULT 0, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), UNIQUE INDEX `PipelineStage_name_key` (`name`));
CREATE TABLE `Business` (`id` VARCHAR(191) NOT NULL, `name` VARCHAR(191) NOT NULL, `address` VARCHAR(191) NULL, `websiteUrl` VARCHAR(191) NULL, `websiteStatus` ENUM('UNKNOWN','NO_WEBSITE','HAS_WEBSITE','NEEDS_VERIFICATION') NOT NULL DEFAULT 'UNKNOWN', `instagramUrl` VARCHAR(191) NULL, `otherSocialUrl` VARCHAR(191) NULL, `contactPerson` VARCHAR(191) NULL, `phone` VARCHAR(191) NULL, `email` VARCHAR(191) NULL, `leadSource` VARCHAR(191) NULL, `sourceUrl` VARCHAR(191) NULL, `priority` ENUM('LOW','MEDIUM','HIGH') NOT NULL DEFAULT 'MEDIUM', `notes` TEXT NULL, `nicheId` VARCHAR(191) NULL, `stageId` VARCHAR(191) NOT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `Business_name_idx` (`name`), INDEX `Business_websiteStatus_idx` (`websiteStatus`), INDEX `Business_priority_idx` (`priority`), INDEX `Business_stageId_idx` (`stageId`), INDEX `Business_nicheId_idx` (`nicheId`));
CREATE TABLE `Audit` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `auditDate` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `websiteCondition` VARCHAR(191) NULL, `mobileExperience` VARCHAR(191) NULL, `designPerformance` TEXT NULL, `problems` TEXT NULL, `opportunities` TEXT NULL, `evidenceUrl` VARCHAR(191) NULL, `notes` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `Audit_businessId_auditDate_idx` (`businessId`, `auditDate`));
CREATE TABLE `OutreachActivity` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `occurredAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `channel` ENUM('WHATSAPP','EMAIL','INSTAGRAM','PHONE','IN_PERSON','OTHER') NOT NULL, `activityType` ENUM('INITIAL_CONTACT','FOLLOW_UP','RESPONSE_RECEIVED','MEETING','OTHER') NOT NULL, `response` ENUM('NO_RESPONSE','POSITIVE','NEUTRAL','NEGATIVE','NOT_APPLICABLE') NOT NULL DEFAULT 'NOT_APPLICABLE', `notes` TEXT NULL, `followUpDate` DATETIME(3) NULL, `followUpStatus` ENUM('PENDING','COMPLETED','CANCELED') NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), INDEX `OutreachActivity_businessId_occurredAt_idx` (`businessId`, `occurredAt`), INDEX `OutreachActivity_followUpDate_followUpStatus_idx` (`followUpDate`, `followUpStatus`));
CREATE TABLE `Deal` (`id` VARCHAR(191) NOT NULL, `businessId` VARCHAR(191) NOT NULL, `serviceType` VARCHAR(191) NOT NULL, `status` ENUM('QUALIFICATION','PROPOSAL','NEGOTIATION','WON','LOST') NOT NULL DEFAULT 'QUALIFICATION', `estimatedValue` BIGINT NULL, `proposalDate` DATETIME(3) NULL, `closedDate` DATETIME(3) NULL, `notes` TEXT NULL, `createdAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updatedAt` DATETIME(3) NOT NULL, PRIMARY KEY (`id`), INDEX `Deal_businessId_status_idx` (`businessId`, `status`));
ALTER TABLE `Business` ADD CONSTRAINT `Business_nicheId_fkey` FOREIGN KEY (`nicheId`) REFERENCES `Niche`(`id`) ON DELETE SET NULL ON UPDATE CASCADE;
ALTER TABLE `Business` ADD CONSTRAINT `Business_stageId_fkey` FOREIGN KEY (`stageId`) REFERENCES `PipelineStage`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE `Audit` ADD CONSTRAINT `Audit_businessId_fkey` FOREIGN KEY (`businessId`) REFERENCES `Business`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `OutreachActivity` ADD CONSTRAINT `OutreachActivity_businessId_fkey` FOREIGN KEY (`businessId`) REFERENCES `Business`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE `Deal` ADD CONSTRAINT `Deal_businessId_fkey` FOREIGN KEY (`businessId`) REFERENCES `Business`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
